-- Wrap auth.uid() in RLS policy predicates in (SELECT ...) so Postgres evaluates it once
-- per statement (InitPlan) instead of once per row -- the Supabase-documented RLS perf
-- pattern. Predicate-equivalent (row visibility unchanged). Generated by
-- 'pgrls fix --rule PERF001' and verified (PERF001 -> 0). Refs #50.

-- [PERF001] Wrap auth function call(s) in policy 'Share managers can update requests' on public.access_requests so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Share managers can update requests" ON public.access_requests
    USING (can_manage_shares((SELECT auth.uid()), resource_type, resource_id));

-- [PERF001] Wrap auth function call(s) in policy 'Users can view own requests or requests they manage' on public.access_requests so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can view own requests or requests they manage" ON public.access_requests
    USING (requester_id = (SELECT auth.uid()) OR can_manage_shares((SELECT auth.uid()), resource_type, resource_id));

-- [PERF001] Wrap auth function call(s) in policy 'Users can delete their own conversations' on public.agent_conversations so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can delete their own conversations" ON public.agent_conversations
    USING (created_by = (SELECT auth.uid()));

