-- [PERF001] Wrap auth function call(s) in policy 'Channel members can view members' on public.channel_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Channel members can view members" ON public.channel_members
    USING (can_access_channel(channel_id, (SELECT auth.uid())));

-- [PERF001] Wrap auth function call(s) in policy 'Channel owners can remove members' on public.channel_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Channel owners can remove members" ON public.channel_members
    USING (user_id = (SELECT auth.uid()) OR EXISTS (SELECT 1 FROM channel_members AS cm WHERE cm.channel_id = channel_members.channel_id AND cm.user_id = auth.uid() AND cm.role = ANY(ARRAY[CAST('owner' AS text), CAST('moderator' AS text)])));

