ALTER POLICY "Users can view accessible channels" ON public.channels
    USING (can_access_workspace_app(workspace_app_id, (SELECT auth.uid())) AND ((is_dm = FALSE AND is_private = FALSE) OR (is_private = TRUE AND is_dm = FALSE AND (created_by = (SELECT auth.uid()) OR EXISTS (SELECT 1 FROM channel_members WHERE channel_members.channel_id = channels.id AND channel_members.user_id = auth.uid()))) OR (is_dm = TRUE AND (SELECT auth.uid()) = ANY(dm_participants))));

